    ["Garde l'étincelle de butin du jeu allumée."] = "Mantém o brilho de saque do jogo ativado.",
    ["Garder les apparences que je n'ai pas"] = "Manter as aparências que eu não tenho",
    ["Garder les derniers messages"] = "Manter as últimas mensagens",
