    ["Groupe"] = "Grupo",
    ["Groupe (%d)"] = "Grupo (%d)",
    ["Groupes, duels et invocations"] = "Grupos, duelos e invocações",
    ["Groupes, duels et invocations acceptés ou refusés pour toi ; une interface plus calme."] = "Grupos, duelos e invocações aceitos ou recusados por você; uma interface mais tranquila.",
    ["Guerrier"] = "Guerreiro",
    ["Guerrier : Fulgurance, Vengeance, Exécution, Ivresse de la victoire. Voleur : Riposte. Chasseur : Contre-attaque, Morsure de la mangouste, Ordre de tuer. Paladin : Marteau de courroux. Exemple : tu pares un coup, Riposte apparaît avec sa touche. Coupé, ces sorts ne sont plus annoncés (sauf s'ils brillent et que « Sorts qui brillent » est actif)."] = "Guerreiro: Dominar, Vingança, Execução, Ímpeto da Vitória. Ladino: Revide. Caçador: Contra-ataque, Mordida de Mangusto, Ordem de Matar. Paladino: Martelo da Ira. Exemplo: você aparou um golpe, Revide aparece com a tecla. Desativado, esses feitiços não são mais anunciados (exceto se brilharem e \"Feitiços que brilham\" estiver ativo).",
    ["Guerrier : une petite icône quand le buff est actif."] = "Guerreiro: um pequeno ícone quando o bônus está ativo.",
    ["Guilde"] = "Guilda",
    ["HDV"] = "CL",
    ["HDV : %s ne sera plus proposé (/pp hdv exclus pour la liste)"] = "CL: %s não será mais sugerido (/pp hdv exclus para ver a lista)",
    ["HDV : %s refusé"] = "CL: %s recusado",
    ["HDV : %s refusé (%s)"] = "CL: %s recusado (%s)",
    ["HDV : coche d'abord les objets à mettre en vente (clic sur la ligne)"] = "CL: marque primeiro os itens a pôr à venda (clique na linha)",
    ["HDV : le jeu demande une confirmation pour %s. Clique encore (ou ta touche) pour confirmer."] = "CL: o jogo pede uma confirmação para %s. Clique de novo (ou sua tecla) para confirmar.",
    ["HDV : le scan complet n'a rien renvoyé."] = "CL: a varredura completa não retornou nada.",
    ["HDV : le serveur n'autorise un scan complet que toutes les 15 min, réessaie dans %d min."] = "CL: o servidor só permite uma varredura completa a cada 15 min, tente de novo em %d min.",
    ["HDV : pas de réponse au scan complet, réessaie plus tard."] = "CL: sem resposta à varredura completa, tente mais tarde.",
    ["HDV : prix trouvés."] = "CL: preços encontrados.",
    ["HDV : recherche des prix en cours, patiente un instant"] = "CL: buscando preços, aguarde um instante",
    ["HDV : rien de prêt à mettre en vente"] = "CL: nada pronto para pôr à venda",
    ["HDV : scan complet lancé (tous les prix de l'HDV, quelques secondes)..."] = "CL: varredura completa iniciada (todos os preços da Casa de leilões, alguns segundos)...",
    ["HDV : scan complet refusé par le jeu"] = "CL: varredura completa recusada pelo jogo",
