    ["Réputations indisponibles sur ce client."] = "Reputações indisponíveis neste cliente.",
    ["Résistance : %s"] = "Resistência: %s",
    ["Résistances"] = "Resistências",
    ["Rétablir mes anciens réglages"] = "Restaurar minhas opções antigas",
    ["Rétablit la touche par défaut de Platyplus ((aucune))."] = "Restaura a tecla padrão do Platyplus ((nenhuma)).",
    ["Rétablit la touche par défaut de Platyplus (F)."] = "Restaura a tecla padrão do Platyplus (F).",
    ["S'il te manque en combat : son icône et sa touche, comme une alerte de proc."] = "Se estiver faltando em combate: o ícone e a tecla dele, como um alerta de proc.",
    ["S'ouvre avec la touche des sacs, chez le marchand, à la banque ou au courrier."] = "Abre com a tecla das bolsas, no vendedor, no banco ou no correio.",
    ["Sacs"] = "Bolsas",
    ["Saison %d"] = "Temporada %d",
    ["Sans Alt, et gardé d'une session à l'autre."] = "Sem Alt, e guardado de uma sessão para outra.",
    ["Sans appuyer sur rien. Maintiens Maj en parlant au PNJ pour faire une pause."] = "Sem pressionar nada. Mantenha Shift ao falar com o PNJ para fazer uma pausa.",
    ["Sans rang"] = "Sem posto",
    ["Scan complet automatique"] = "Varredura completa automática",
    ["Se remplit à la vitesse de ton arme et repart à chaque coup blanc (le jeu le signale lui-même). Le temps restant s'affiche à droite. Elle devient dorée quand Frappe héroïque ou Enchaînement attend le prochain coup, et pâlit quand ta cible est hors de portée."] = "Enche-se na velocidade da sua arma e recomeça a cada golpe branco (o próprio jogo sinaliza). O tempo restante aparece à direita. Fica dourada quando Golpe Heroico ou Rachar aguarda o próximo golpe e esmaece quando seu alvo está fora de alcance.",
    ["Se vend le plus cher"] = "Vende pelo maior preço",
    ["Sens d'empilement"] = "Sentido de empilhamento",
    ["Ses réglages"] = "Suas opções",
    ["Session"] = "Sessão",
    ["Seuil d'alerte"] = "Limite do alerta",
    ["Seul, tu sais déjà que les mobs te tapent : la fenêtre ne s'affiche pas."] = "Sozinho, você já sabe que as criaturas atacam você: a janela não aparece.",
    ["Seulement en combat"] = "Somente em combate",
    ["Seulement en combat."] = "Somente em combate.",
    ["Seulement en groupe"] = "Somente em grupo",
    ["Si l'addon Threat Plates est actif, il remplace les plates du jeu : désactive-le pour voir celles-ci. Les cadavres à fouiller ont déjà leurs étincelles (onglet Butin). /pp plates : ce que voit chaque plate."] = "Se o addon Threat Plates estiver ativo, ele substitui as placas do jogo: desative-o para ver estas. Os cadáveres a saquear já têm seus brilhos (aba Saque). /pp plates: o que cada placa vê.",
    ["Si le marchand t'en donne autant ou plus, l'objet n'est pas mis en vente."] = "Se o vendedor pagar o mesmo ou mais, o item não é posto à venda.",
    ["Si ta guilde l'autorise, la réparation est payée par la banque de guilde ; sinon, avec ton argent."] = "Se a sua guilda permitir, o reparo é pago pelo banco da guilda; senão, com o seu dinheiro.",
    ["Si tu fais des dégâts : vert quand le mob t'ignore, orange quand ça se joue, rouge quand il t'attaque. Si tu tankes, c'est l'inverse : rouge, il t'échappe."] = "Se você causa dano: verde quando a criatura ignora você, laranja quando está em disputa, vermelho quando ela ataca você. Se você é tanque, é o inverso: vermelho, ela escapa de você.",
    ["Soins (pas interruptible)"] = "Cura (não interrompível)",
    ["Son quand ta cible incante"] = "Som quando seu alvo lança um feitiço",
    ["Son à l'apparition"] = "Som ao aparecer",
    ["Sorts ajoutés"] = "Feitiços adicionados",
    ["Sorts ignorés"] = "Feitiços ignorados",
    ["Sorts qui brillent"] = "Feitiços que brilham",
    ["Sorts réactifs de ma classe"] = "Feitiços reativos da minha classe",
    ["Sorts surveillés"] = "Feitiços monitorados",
    ["Souris %s"] = "Mouse %s",
    ["Sous le seuil, la barre devient rouge et clignote."] = "Abaixo do limite, a barra fica vermelha e pisca.",
    ["Spé 2"] = "Spec 2",
    ["Style Platyplus"] = "Estilo Platyplus",
    ["Styles prêts à l'emploi :"] = "Estilos prontos para usar:",
    ["Suivant"] = "Próximo",
    ["Suivre aussi les /roll"] = "Acompanhar também os /roll",
    ["Suivre les jets de butin"] = "Acompanhar os dados de saque",
    ["Suivre sur la barre"] = "Acompanhar na barra",
    ["Sur ce personnage"] = "Neste personagem",
    ["Sur la fiche du personnage"] = "Na ficha do personagem",
    ["Sur la plate : ta progression de quête (« 3/8 ») et l'étiquette « Rare »."] = "Na placa: seu progresso de missão (« 3/8 ») e a etiqueta « Raro ».",
    ["Sur les grandes cartes de l'accueil, la tranche de niveau prend la même couleur et une pastille « À ton niveau » ou « Bientôt » s'ajoute. La première fois que tu ouvres l'accueil, il défile jusqu'aux donjons de ton niveau."] = "Nos cartões grandes da página inicial, a faixa de nível recebe a mesma cor e uma etiqueta \"No seu nível\" ou \"Em breve\" é adicionada. Na primeira vez que você abre a página inicial, ela rola até as masmorras do seu nível.",
    ["Sur les objets des sacs"] = "Nos itens das bolsas",
    ["Système"] = "Sistema",
    ["Sûr ? (re-clique)"] = "Tem certeza? (clique de novo)",
    ["Ta cible"] = "Seu alvo",
    ["Ta cible esquive : l'icône de Fulgurance apparaît avec « 3 » dessous si elle est sur la touche 3."] = "Seu alvo esquiva: o ícone de Dominar aparece com \"3\" embaixo se ele estiver na tecla 3.",
    ["Ta position sur la carte de la zone."] = "Sua posição no mapa da zona.",
    ["Ta touche"] = "Sua tecla",
    ["Tabard"] = "Tabardo",
    ["Taille"] = "Tamanho",
    ["Taille de l'icône"] = "Tamanho do ícone",
    ["Taille de la fenêtre"] = "Tamanho da janela",
    ["Taille des messages dans la fenêtre de chat Platyplus."] = "Tamanho das mensagens na janela de chat Platyplus.",
    ["Taille des plates"] = "Tamanho das placas",
    ["Taille du texte"] = "Tamanho do texto",
    ["Taille, nombre, animation et son des alertes."] = "Tamanho, número, animação e som dos alertas.",
    ["Taille, épaisseur, texture, transparence."] = "Tamanho, espessura, textura, transparência.",
    ["Tank : en haut, les mobs que tu n'as pas ou que tu perds. DPS : en haut, ceux qui te tapent. Par vie : impossible quand le jeu cache la vie des mobs (ordre d'arrivée dans ce cas)."] = "Tanque: no topo, as criaturas que você não controla ou está perdendo. DPS: no topo, as que atacam você. Por vida: impossível quando o jogo oculta a vida das criaturas (ordem de chegada nesse caso).",
    ["Tank : il tape un allié. DPS/soins : il te tape."] = "Tanque: ela ataca um aliado. DPS/cura: ela ataca você.",
    ["Tank : le mob te tape. DPS/soins : il ne te regarde pas."] = "Tanque: a criatura ataca você. DPS/cura: ela nem olha para você.",
    ["Tank : quand un mob qui te tapait part sur un allié, sa plate clignote pour que tu le reprennes (Provocation, Coup railleur...)."] = "Tanque: quando uma criatura que atacava você passa para um aliado, a placa dela pisca para você retomá-la (Provocar, Golpe Zombeteiro...).",
    ["Tank : seulement les mobs que je n'ai pas"] = "Tanque: só as criaturas que não controlo",
    ["Tank : un éclat rouge sur la ligne d'un mob qui te tapait et tape maintenant quelqu'un d'autre. Sans son."] = "Tanque: um lampejo vermelho na linha de uma criatura que atacava você e agora ataca outra pessoa. Sem som.",
    ["Tape /pp ou clique sur l'icône Platyplus : chaque fonction a son interrupteur, et chaque réglage s'explique quand tu le survoles. Pour revoir cette visite : /pp bienvenue."] = "Digite /pp ou clique no ícone Platyplus: cada função tem seu interruptor, e cada ajuste é explicado quando você passa o mouse sobre ele. Para rever esta visita: /pp welcome.",
    ["Tapé par d'autres"] = "Atacado por outros",
    ["Temps de jeu actif"] = "Tempo de jogo ativo",
    ["Temps de réponse du serveur, en millisecondes."] = "Tempo de resposta do servidor, em milissegundos.",
    ["Temps pendant lequel une ligne reste affichée avant de s'estomper."] = "Tempo em que uma linha fica exibida antes de sumir.",
    ["Temps restant"] = "Tempo restante",
    ["Temps écoulé · gagnant inconnu"] = "Tempo esgotado · vencedor desconhecido",
    ["Tenu par un autre tank"] = "Segurado por outro tanque",
    ["Terminer"] = "Concluir",
    ["Tes mots à masquer"] = "Suas palavras a ocultar",
    ["Tes sacs à la suite dans une grille. Les cases sont celles du jeu : clic droit pour utiliser ou vendre, glisser pour déplacer, Maj-clic pour lier ou partager une pile. Exemple : tape « lin » dans Chercher, seules tes Étoffes de lin restent allumées. Tire le bandeau pour déplacer la fenêtre. Coupé : les sacs du jeu reviennent."] = "Suas bolsas em sequência em uma grade. As casas são as do jogo: clique direito para usar ou vender, arrastar para mover, Shift+clique para linkar ou dividir uma pilha. Exemplo: digite \"linho\" em Buscar, só os seus Tecidos de Linho continuam acesos. Arraste a faixa para mover a janela. Desativado: as bolsas do jogo voltam.",
    ["Tester"] = "Testar",
    ["Texte dans la couleur du canal"] = "Texto na cor do canal",
    ["Texte de statut du jeu : écrit les valeurs exactes sur les barres de vie et de ressource."] = "Texto de status do jogo: escreve os valores exatos nas barras de vida e de recurso.",
    ["Texture"] = "Textura",
    ["Threat Plates"] = "Threat Plates",
    ["Tire son bandeau pour la déplacer : elle s'ouvrira ensuite toujours à cet endroit."] = "Arraste a faixa para movê-la: ela passará a abrir sempre nesse lugar.",
    ["Titre : %s"] = "Título: %s",
    ["Ton mode"] = "Seu modo",
    ["Ton niveau"] = "Seu nível",
    ["Ton nom apparaît en jaune dans le message, un petit son est joué (au plus toutes les 3 secondes) et l'icône du jeu clignote dans la barre des tâches si tu es sur une autre fenêtre. Les chuchotements ont déjà leur son dans le jeu."] = "Seu nome aparece em amarelo na mensagem, um pequeno som é tocado (no máximo a cada 3 segundos) e o ícone do jogo pisca na barra de tarefas se você estiver em outra janela. Os sussurros já têm som no jogo.",
    ["Ton nom surligné, avec un son"] = "Seu nome destacado, com som",
    ["Ton prix"] = "Seu preço",
    ["Ton prix = le moins cher des autres vendeurs, moins ce montant en pièces de cuivre (au moins 1 pc de moins, pour passer devant). Si le moins cher est déjà à toi, tu t'alignes dessus au lieu de te concurrencer."] = "Seu preço = o mais barato dos outros vendedores, menos este valor em moedas de cobre (pelo menos 1 pc a menos, para ficar na frente). Se o mais barato já for seu, você se alinha a ele em vez de competir consigo mesmo.",
    ["Ton raccourci vers tout Platyplus, posé où tu veux à l'écran."] = "Seu atalho para todo o Platyplus, posicionado onde você quiser na tela.",
    ["Ton équipement est réparé dès que tu parles à un marchand qui sait réparer."] = "Seu equipamento é reparado assim que você fala com um vendedor que sabe reparar.",
    ["Ton équipement est réparé, avec l'argent de la guilde quand c'est possible."] = "Seu equipamento é reparado, com o dinheiro da guilda quando possível.",
    ["Total des composants"] = "Total dos componentes",
    ["Total estimé : %s"] = "Total estimado: %s",
    ["Total pour %d"] = "Total para %d",
    ["Touche : %s"] = "Tecla: %s",
    ["Touche d'interaction"] = "Tecla de interação",
    ["Touche de mise en vente"] = "Tecla de venda",
    ["Touche pour boire"] = "Tecla para beber",
    ["Touche pour manger"] = "Tecla para comer",
    ["Toujours vendre"] = "Sempre vender",
    ["Toujours vendre : %d"] = "Sempre vender: %d",
    ["Tous les mobs en combat avec ton groupe, et qui les tient."] = "Todas as criaturas em combate com o seu grupo e quem as controla.",
    ["Tous les réglages dans l'onglet"] = "Todos os ajustes na aba",
    ["Tous les réglages dans les onglets"] = "Todos os ajustes nas abas",
    ["Tous tes mobs sont tenus."] = "Todas as suas criaturas estão controladas.",
    ["Tous tes sacs dans une seule fenêtre Platyplus, avec recherche, tri, argent et places libres."] = "Todas as suas bolsas em uma única janela Platyplus, com busca, organização, dinheiro e espaços livres.",
    ["Tous tes sacs dans une seule fenêtre."] = "Todas as suas bolsas em uma única janela.",
    ["Tout allumé, avec les automatismes : invitations, invocations, courrier…"] = "Tudo ligado, com as automações: convites, invocações, correio…",
    ["Tout appliquer"] = "Aplicar tudo",
    ["Tout cocher"] = "Marcar tudo",
    ["Tout coupé sauf l'icône : tu allumes seulement ce que tu veux."] = "Tudo desligado menos o ícone: você liga só o que quiser.",
    ["Tout décocher"] = "Desmarcar tudo",
    ["Tout est prêt !"] = "Tudo pronto!",
    ["Tout est ramassé d'un coup, et tu vois ce que tu gagnes sans ouvrir tes sacs."] = "Tudo é saqueado de uma vez, e você vê o que ganha sem abrir as bolsas.",
    ["Tout est ramassé dès l'ouverture, sans fenêtre de butin."] = "Tudo é saqueado ao abrir, sem janela de saque.",
    ["Tout le contenu d'un cadavre ou d'un coffre est ramassé dès l'ouverture."] = "Todo o conteúdo de um cadáver ou baú é saqueado assim que é aberto.",
    ["Tout le monde a passé"] = "Todos passaram",
    ["Tout remettre par défaut"] = "Restaurar tudo ao padrão",
    ["Tout réinitialiser"] = "Redefinir tudo",
    ["Tout réinitialiser (garder mes listes)"] = "Redefinir tudo (manter minhas listas)",
    ["Tout se règle avec /pp"] = "Tudo se ajusta com /pp",
    ["Tout sort que le jeu entoure d'une lueur sur tes barres : c'est le cas des procs des autres classes."] = "Qualquer feitiço que o jogo contorna com um brilho nas suas barras: é o caso dos procs das outras classes.",
    ["Tout va bien"] = "Tudo certo",
    ["Toutes les fonctions sont coupées, sauf l'icône Platyplus qui ouvre les options. Le jeu redevient presque comme sans l'addon ; allume ensuite ce que tu veux, onglet par onglet."] = "Todas as funções estão desligadas, exceto o ícone Platyplus que abre as opções. O jogo fica quase como sem o addon; depois ligue o que quiser, aba por aba.",
    ["Toutes tes quêtes sont faites (%d)"] = "Todas as suas missões estão concluídas (%d)",
    ["Traducteur"] = "Tradutor",
    ["Traduit le chat des joueurs étrangers avec une petite IA qui tourne sur ton PC (programme « Traducteur Platyplus », à lancer à côté du jeu)."] = "Traduz o chat de jogadores estrangeiros com uma pequena IA que roda no seu PC (programa \"Tradutor Platyplus\", para abrir ao lado do jogo).",
    ["Trier les sacs"] = "Organizar as bolsas",
    ["Très rond"] = "Bem redondo",
    ["Tu es en train de le perdre"] = "Você está perdendo",
    ["Tu le tiens"] = "Você segura",
    ["Tu n'as choisi personne à la main."] = "Você não escolheu ninguém manualmente.",
    ["Tu pourras choisir un de ces objets :"] = "Você poderá escolher um destes itens:",
    ["Tu recevras :"] = "Você receberá:",
    ["Tu recevras aussi :"] = "Você também receberá:",
    ["Tu vas prendre l'aggro"] = "Você vai pegar a aggro",
    ["Témoin : clique ici pour te cibler toi-même"] = "Controle: clique aqui para selecionar a si mesmo",
    ["Un ! jaune pour un mob à tuer, un sac pour un mob qui laisse un objet de quête, avec ta progression. Disparaît quand l'objectif est fini. Les objectifs de tes équipiers sont ignorés."] = "Um ! amarelo para uma criatura a matar, uma bolsa para uma criatura que deixa um item de missão, com o seu progresso. Some quando o objetivo termina. Os objetivos dos seus companheiros são ignorados.",
    ["Un 2e /roll du même joueur pour le même objet est signalé et ne compte pas. Une égalité au plus haut dé est signalée."] = "Um 2º /roll do mesmo jogador para o mesmo item é sinalizado e não conta. Um empate no maior dado é sinalizado.",
    ["Un add-on n'a ni Internet ni IA : la traduction est faite par le programme Traducteur Platyplus (dossier Platyplus\\Traducteur), qui s'affiche par-dessus le jeu. Clic sur [FR] : une fine bande de couleurs apparaît une demi-seconde en haut à gauche de l'écran, le programme la lit et traduit. Clic droit sur [FR] : le message dans une zone à copier (Ctrl+C), si la bande ne passe pas. Dans le jeu, Ctrl+Entrée ouvre une zone où tu écris en français : la traduction est copiée, colle-la dans le chat avec Ctrl+V. Pas de lien sur les messages protégés par le jeu (en instance)."] = "Um addon não tem Internet nem IA: a tradução é feita pelo programa Tradutor Platyplus (pasta Platyplus\\Traducteur), que aparece por cima do jogo. Clique em [FR]: uma fina faixa de cores aparece por meio segundo no alto, à esquerda da tela, e o programa a lê e traduz. Clique direito em [FR]: a mensagem em uma caixa para copiar (Ctrl+C), se a faixa não funcionar. No jogo, Ctrl+Enter abre uma caixa onde você escreve em francês: a tradução é copiada, cole-a no chat com Ctrl+V. Sem link nas mensagens protegidas pelo jogo (em masmorras).",
    ["Un autre joueur l'a touché en premier : pas d'XP ni de butin pour toi."] = "Outro jogador o atacou primeiro: sem XP nem saque para você.",
    ["Un bandeau au milieu de l'écran te signale que la touche utilisera l'objet de quête. Éteint, la touche marche pareil, sans rien afficher."] = "Uma faixa no meio da tela avisa que a tecla usará o item de missão. Desativado, a tecla funciona igual, sem exibir nada.",
    ["Un cadavre qui a encore du butin pour toi brille à l'approche."] = "Um cadáver que ainda tem saque para você brilha ao se aproximar.",
    ["Un chat plus beau, plus lisible, qui se souvient, sans spam."] = "Um chat mais bonito, mais legível, que lembra, sem spam.",
    ["Un chat plus lisible : onglets, anti-spam, et l'historique gardé après un /reload."] = "Um chat mais legível: abas, antispam e o histórico mantido após um /reload.",
    ["Un clic ouvre le lien, prêt à copier (Ctrl+C)."] = "Um clique abre o link, pronto para copiar (Ctrl+C).",
    ["Un clic règle toutes les fonctions d'un coup. Tu ajustes ensuite ce que tu veux, ici ou avec /pp."] = "Um clique ajusta todas as funções de uma vez. Depois você ajusta o que quiser, aqui ou com /pp.",
    ["Un mob qui t'attaquera si tu t'approches."] = "Uma criatura que atacará você se você se aproximar.",
    ["Un mode allume ou coupe toutes les fonctions d'un coup : une base, que tu ajustes ensuite dans les autres onglets. Survole un mode pour voir exactement ce qu'il change."] = "Um modo liga ou desliga todas as funções de uma vez: uma base que você ajusta depois nas outras abas. Passe o mouse sobre um modo para ver exatamente o que ele muda.",
    ["Un mode ne change pas ta touche d'interaction, tes listes (« Ne jamais vendre », sorts ajoutés…), les positions, les tailles, les couleurs ni les réglages du jeu."] = "Um modo não muda sua tecla de interação, suas listas (\"Nunca vender\", feitiços adicionados…), as posições, os tamanhos, as cores nem as opções do jogo.",
    ["Un mode pour commencer"] = "Um modo para começar",
    ["Un panneau à droite de la fenêtre de l'HDV."] = "Um painel à direita da janela da casa de leilões.",
    ["Un petit « tic » quand une alerte apparaît."] = "Um pequeno \"tic\" quando um alerta aparece.",
    ["Un réglage que ton client ne connaît pas est grisé."] = "Uma opção que o seu cliente não reconhece fica esmaecida.",
    ["Un son discret à chaque nouvelle alerte, au plus un par seconde. Exemple : Fulgurance devient prête, tu l'entends sans regarder. Le bouton Aperçu le joue aussi."] = "Um som discreto a cada novo alerta, no máximo um por segundo. Exemplo: Dominar fica pronto, você ouve sem olhar. O botão Prévia também o toca.",
    ["Un son quand ta cible commence un sort que tu peux interrompre (au plus une fois par seconde)."] = "Um som quando seu alvo começa um feitiço que você pode interromper (no máximo uma vez por segundo).",
    ["Un sort ajouté ici est annoncé dès qu'il est sur une de tes barres, utilisable et hors recharge, comme un sort réactif. Exemple : ajoute Coup de bouclier pour voir son icône et sa touche chaque fois qu'il est prêt. Glisse le sort depuis ton grimoire, ou tape son nom. En combat, si le jeu cache la recharge, un sort ajouté peut rester affiché pendant sa recharge."] = "Um feitiço adicionado aqui é anunciado assim que está em uma das suas barras, utilizável e sem recarga, como um feitiço reativo. Exemplo: adicione Golpe de Escudo para ver o ícone e a tecla dele toda vez que estiver pronto. Arraste o feitiço do seu grimório ou digite o nome. Em combate, se o jogo ocultar a recarga, um feitiço adicionado pode continuar exibido durante a recarga.",
    ["Un sort ignoré n'a jamais d'alerte, même s'il brille. Exemple : un sort qui brille tout le temps et t'encombre l'écran : ajoute-le ici. Tous les rangs du sort sont ignorés (reconnus par leur nom)."] = "Um feitiço ignorado nunca tem alerta, mesmo que brilhe. Exemplo: um feitiço que brilha o tempo todo e polui sua tela: adicione-o aqui. Todos os níveis do feitiço são ignorados (reconhecidos pelo nome).",
    ["Un souci ? Tape /pp etincelles : il montre ce que Platyplus voit autour de toi."] = "Algum problema? Digite /pp etincelles: ele mostra o que o Platyplus vê ao seu redor.",
    ["Un souci, une idée ? Écris-nous sur github.com/bloufed/Platyplus."] = "Um problema, uma ideia? Escreva para nós em github.com/bloufed/Platyplus.",
    ["Une barre de mana pour le soigneur de ton groupe, posée où tu veux à l'écran : son nom et « 4 320 / 6 800 »."] = "Uma barra de mana para o curador do seu grupo, posicionada onde você quiser na tela: o nome dele e \"4.320 / 6.800\".",
    ["Une barre qui se remplit jusqu'à ton prochain coup automatique. Visible en combat seulement."] = "Uma barra que se enche até o seu próximo golpe automático. Visível apenas em combate.",
    ["Une base de réglages en un clic : Recommandé, Complet, Immersif ou Minimal."] = "Uma base de ajustes em um clique: Recomendado, Completo, Imersivo ou Mínimo.",
    ["Une colonne collée au journal, avec tous les donjons dans l'ordre des niveaux : un clic ouvre un donjon, depuis n'importe quelle page. La tranche de niveau est en couleur selon ton niveau (vert : à ton niveau, or : bientôt, rouge : trop dur, gris : dépassé), et à droite tes quêtes faites (par exemple 2/7, ✓ quand tout est fait). « Accueil » ramène aux grandes cartes."] = "Uma coluna junto ao diário, com todas as masmorras em ordem de nível: um clique abre uma masmorra, de qualquer página. A faixa de nível é colorida conforme o seu nível (verde: no seu nível, ouro: em breve, vermelho: difícil demais, cinza: ultrapassado) e, à direita, suas missões concluídas (por exemplo 2/7, ✓ quando tudo está feito). \"Início\" volta aos cartões grandes.",
    ["Une couleur à part quand un autre tank du groupe tient le mob."] = "Uma cor à parte quando outro tanque do grupo controla a criatura.",
    ["Une fine barre en dessous si tu as deux armes."] = "Uma barra fina embaixo se você tiver duas armas.",
    ["Une icône posée où tu veux à l'écran (hors minicarte). Clic gauche : cette fenêtre. Clic droit : un menu pour allumer ou couper les fonctions. Glisse-la pour la déplacer."] = "Um ícone posicionado onde você quiser na tela (fora do minimapa). Clique esquerdo: esta janela. Clique direito: um menu para ativar ou desativar as funções. Arraste-o para movê-lo.",
    ["Une ligne par mob : nom, vie, qui le tient, ta menace. Vert : tu l'as, orange : tu le perds, rouge : tu ne l'as plus, bleu : un autre tank le tient, gris : il n'a pas de cible. DPS : rouge = il te tape (compteur « N sur toi »)."] = "Uma linha por criatura: nome, vida, quem a controla, sua ameaça. Verde: você a controla, laranja: você a está perdendo, vermelho: você não a controla mais, azul: outro tanque a controla, cinza: ela não tem alvo. DPS: vermelho = ataca você (contador \"N em você\").",
    ["Une ligne « HDV » sur les objets : sacs, équipement porté, liens..."] = "Uma linha \"Casa de leilões\" nos itens: bolsas, equipamento usado, links...",
    ["Une liste « Ne jamais vendre » protège ce que tu veux garder, et un aperçu montre ce qui partira."] = "Uma lista « Nunca vender » protege o que você quer guardar, e uma prévia mostra o que será vendido.",
    ["Une mise en vente par clic"] = "Um item à venda por clique",
    ["Une petite icône à droite des alertes tant que tu as le buff Maîtrise du blocage."] = "Um pequeno ícone à direita dos alertas enquanto você tiver o bônus Maestria de Bloqueio.",
    ["Une pierre de soins"] = "Uma pedra de cura",
    ["Une pièce n'est vendue que si son niveau d'objet est inférieur d'au moins ce nombre de points à celui de la pièce équivalente que tu portes."] = "Uma peça só é vendida se o nível de item dela for inferior em pelo menos este número de pontos ao da peça equivalente que você usa.",
    ["Une plante à cueillir scintille quand tu t'en approches, terne de loin, vive à portée, grise si ta compétence est trop basse. Un seul objet brille à la fois. Utilise le ciblage d'interaction du jeu : l'objet le plus proche, jusqu'à environ 15 m, tout autour de toi. Pour cela Platyplus allume « Activer la touche d'interaction » et les icônes d'interaction des objets du monde du jeu, et les remet comme avant quand tu coupes toutes les étincelles ci-dessous. Pas d'étincelle pendant un combat."] = "Uma planta a colher cintila quando você se aproxima: opaca de longe, viva ao alcance, cinza se a sua habilidade for baixa demais. Só um objeto brilha por vez. Usa a seleção de interação do jogo: o objeto mais próximo, até cerca de 15 m, ao seu redor. Para isso o Platyplus ativa \"Ativar a tecla de interação\" e os ícones de interação dos objetos do mundo do jogo, e os restaura como estavam quando você desativa todos os brilhos abaixo. Sem brilho durante o combate.",
    ["Une seule fenêtre pour tous les sacs"] = "Uma única janela para todas as bolsas",
    ["Une seule touche pour tout : PNJ, coffres, plantes, cadavres à dépouiller, dialogues et quêtes."] = "Uma única tecla para tudo: PNJs, baús, plantas, cadáveres para esfolar, diálogos e missões.",
    ["Une touche pour interagir, parler et rendre les quêtes ; deux pour manger et boire."] = "Uma tecla para interagir, falar e entregar missões; duas para comer e beber.",
    ["Une touche pour parler aux PNJ, ramasser le butin et rendre les quêtes ; des alertes de combat, la menace lisible sur les mobs, la vente automatique, des fenêtres plus claires et bien plus. Tous les réglages sont dans la fenêtre de Platyplus (tu peux aussi taper /pp)."] = "Uma tecla para falar com PNJs, saquear e entregar missões; alertas de combate, ameaça legível nas criaturas, venda automática, janelas mais claras e muito mais. Todos os ajustes estão na janela do Platyplus (você também pode digitar /pp).",
    ["Une touche pour presque tout"] = "Uma tecla para quase tudo",
    ["Utiliser l'objet de quête au bon endroit"] = "Usar o item de missão no lugar certo",
    ["Utiliser la fenêtre de chat Platyplus"] = "Usar a janela de chat Platyplus",
